input.sparql:
SELECT DISTINCT ?p ?pclass WHERE {
  ?p a brick:AirTemperatureSensor ; ?p rdfs:label ?l . FILTER regex(?l, "Perimeter_bot_ZN_3")
}

SELECT ?p ?l WHERE {
  ?p rdfs:label ?l . FILTER regex(?l, "Perimeter_bot_ZN_3")
} LIMIT 30

SELECT ?p ?l ?c WHERE {
  ?p rdfs:label ?l . FILTER regex(?l, "ZN_3")
  OPTIONAL { ?p a ?c }
} LIMIT 50

SELECT ?p ?l WHERE {
  ?p rdfs:label ?l . FILTER regex(?l, "Air ?Temperature|Temperature")
} LIMIT 50

SELECT ?p ?l ?c ?ts WHERE {
  ?p brick:hasLocation ?loc .
  FILTER (?loc = uri("http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02"))
  ?p rdfs:label ?l .
  OPTIONAL { ?p a ?c }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 50

SELECT ?p ?l ?ts WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor ;
     rdfs:label ?l ;
     brick:hasLocation ?loc .
  FILTER (?loc = uri("http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02"))
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 50

SELECT ?p ?l ?ts WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor ;
     rdfs:label ?l .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 60

SELECT ?p ?l WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?p rdfs:label ?l }
} LIMIT 60
